// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { evolvePath } from "@remotion/paths";

{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type NeonFlowTagProps = Record<string, any>;

const NeonFlowTag: React.FC<NeonFlowTagProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  titleText = "malloy studio",
  glowIntensity = 20,
  line1Color = "#00f2ff", // Cyan
  line2Color = "#9d00ff", // Purple
  line3Color = "#0066ff", // Blue
  line4Color = "#ff7b00", // Orange
  tagColor = "#ffffff",
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Background handling
  const bgColor = transparentBackground ? "#00000000" : backgroundColor;

  // Animation Timing
  const entranceDuration = fps * 1.5;
  const springConfig = { damping: 200, stiffness: 100, mass: 2 };

  // Master progress for wave amplitude scaling
  const progress = spring({
    frame,
    fps,
    config: springConfig,
    durationInFrames: entranceDuration,
  });

  // Staggered Line Entrances
  const prog3 = spring({ 
    frame: frame, 
    fps, 
    config: springConfig, 
    durationInFrames: entranceDuration 
  });
  
  const prog2 = spring({ 
    frame: frame - 15, 
    fps, 
    config: springConfig, 
    durationInFrames: entranceDuration 
  });

  const prog4 = spring({ 
    frame: frame - 30, 
    fps, 
    config: springConfig, 
    durationInFrames: entranceDuration 
  });

  const prog1 = spring({ 
    frame: frame - 45, 
    fps, 
    config: springConfig, 
    durationInFrames: entranceDuration 
  });

  // Pulse Logic for "Battle Ropes" Effect
  // Pulse for thickness/glow
  const pulseOsc = Math.sin(frame / 8); 
  const pulseWidthScale = interpolate(pulseOsc, [-1, 1], [0.85, 1.15]);
  const pulseGlowScale = interpolate(pulseOsc, [-1, 1], [0.8, 1.3]);
  const waveAmplitude = 45; 

  // Tag Position
  const tagX = width * 0.6;
  const tagY = height * 0.5;
  const tagW = 400;
  const tagH = 100;
  const tagLeftX = tagX - tagW / 2 + 40; // Overlap slightly into the tag
  const tagRightX = tagX + tagW / 2 - 40; // Exit point for the grey line

  // Define Lines with Sine Wave Logic
  const generatePath = (
    startX: number,
    startY: number,
    endX: number,
    endY: number,
    offset: number
  ) => {
    // Generate a high-resolution polyline to approximate a smooth sine wave
    const segments = 100; 
    let d = "";

    // Wave Physics
    // Frequency: Adjusted for visual balance (approx 3 waves on screen)
    const frequency = 0.012; 
    // Speed: Controls propagation rate
    const speed = frame / 8;
    
    // Scale amplitude by entrance progress
    const currentAmp = waveAmplitude * progress;

    for (let i = 0; i <= segments; i++) {
      const t = i / segments;
      const x = startX + (endX - startX) * t;
      // Linear interpolation for the base path (fan shape)
      const yBase = startY + (endY - startY) * t;
      
      // Battle Ropes Logic:
      // Wave originates at the Pill (Right) and travels Left (Outward).
      // Phase = distance_from_source * frequency - time
      const distFromPill = endX - x;
      const waveY = Math.sin(distFromPill * frequency - speed + offset) * currentAmp;

      const px = x;
      const py = yBase + waveY;

      if (i === 0) {
        d += `M ${px} ${py}`;
      } else {
        d += ` L ${px} ${py}`;
      }
    }
    
    return d;
  };

  // Line 1 (Cyan): Starts high, converges to center
  const path1 = generatePath(
    -100, height * 0.05,
    tagLeftX, tagY,
    0
  );

  // Line 2 (Purple): Starts mid-high, converges to center
  const path2 = generatePath(
    -100, height * 0.35,
    tagLeftX, tagY,
    1.5
  );

  // Line 3 (Blue): Starts mid-low, converges to center
  const path3 = generatePath(
    -100, height * 0.65,
    tagLeftX, tagY,
    3.0
  );

  // Line 4 (Orange): Starts low, converges to center
  const path4 = generatePath(
    -100, height * 0.95,
    tagLeftX, tagY,
    4.5
  );

  // Evolve Paths using individual staggered springs
  const evolution1 = evolvePath(prog1, path1);
  const evolution2 = evolvePath(prog2, path2);
  const evolution3 = evolvePath(prog3, path3);
  const evolution4 = evolvePath(prog4, path4);

  // Exit Grey Line
  const exitLineStartFrame = fps * 2.5; 
  const exitProgress = spring({
    frame: frame - exitLineStartFrame,
    fps,
    config: { damping: 200, stiffness: 60, mass: 1 },
  });
  
  const exitPath = `M ${tagRightX} ${tagY} L ${width} ${tagY}`;
  const exitEvolution = evolvePath(exitProgress, exitPath);

  // Tag Animation
  const tagScale = spring({
    frame: frame - fps * 0.8,
    fps,
    config: { damping: 15, stiffness: 120 },
  });
  
  const textOpacity = interpolate(frame, [fps, fps + 30], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Styles - Dynamic Pulse Added
  const lineStyle = (color: string, strokeWidth: number) => ({
    fill: "none",
    stroke: color,
    strokeWidth: strokeWidth * pulseWidthScale, // Pulsing thickness
    strokeLinecap: "round" as const,
    strokeLinejoin: "round" as const, // Smooth joins for polyline
    filter: `drop-shadow(0px 0px ${glowIntensity * pulseGlowScale}px ${color})`, // Pulsing glow
    opacity: 0.9,
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* SVG Layer for Lines */}
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", top: 0, left: 0, overflow: "visible" }}
      >
        {/* Exit Line */}
        <path 
          d={exitPath} 
          fill="none"
          stroke="#aaaaaa"
          strokeWidth={4}
          strokeLinecap="round"
          style={{
            filter: "drop-shadow(0px 0px 8px rgba(170,170,170,0.5))",
            opacity: 0.7
          }}
          {...exitEvolution} 
        />

        {/* Weaving Lines - pulsing "battle ropes" */}
        <path d={path3} {...lineStyle(line3Color, 18)} {...evolution3} />
        <path d={path2} {...lineStyle(line2Color, 20)} {...evolution2} />
        <path d={path4} {...lineStyle(line4Color, 16)} {...evolution4} />
        <path d={path1} {...lineStyle(line1Color, 22)} {...evolution1} />
      </svg>

      {/* Tag Layer */}
      <div
        style={{
          position: "absolute",
          left: tagX,
          top: tagY,
          width: tagW,
          height: tagH,
          transform: `translate(-50%, -50%) scale(${tagScale})`,
          transformOrigin: "center center",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: "0 40px",
          borderRadius: 999,
          backgroundColor: `${tagColor}15`,
          backdropFilter: "blur(15px) brightness(1.1)",
          boxShadow: `
            inset 0 0 0 1px ${tagColor}30,
            0 10px 40px -10px rgba(0,0,0,0.5)
          `,
          opacity: Math.min(tagScale, 1),
        }}
      >
        {/* Shine effect on tag */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            borderRadius: 999,
            background: "linear-gradient(120deg, rgba(255,255,255,0) 30%, rgba(255,255,255,0.1) 50%, rgba(255,255,255,0) 70%)",
            opacity: 0.6,
          }}
        />

        {/* Text */}
        <span
          style={{
            fontFamily: "Inter, sans-serif",
            fontSize: 48,
            fontWeight: 600,
            color: tagColor,
            opacity: textOpacity,
            letterSpacing: "-0.02em",
            textShadow: `0 0 20px ${tagColor}80`,
          }}
        >
          {titleText}
        </span>
      </div>
      
    </AbsoluteFill>
  );
};

export default NeonFlowTag;